VRT_L("tle-c-svt-r31",{"duree":20,"titre":"Glycémie : variations et régulation hormonale","accroche":"Insuline et glucagon, deux hormones antagonistes.","intro":"Le pancréas ajuste la glycémie grâce à deux hormones.","objectifs":["préciser les rôles","interpréter l'expérience du foie lavé","expliquer la régulation"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>glycémie</strong> est la concentration de glucose dans le sang. À jeun, elle est voisine de 1 g/L.</div>"},{"t":"Les deux hormones","verrou":true},{"t":"Le foie lavé","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":31,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"En TP à Mbouda, on rince un foie frais jusqu'à ce que l'eau ne contienne plus de glucose (test négatif à la liqueur de Fehling) ; après 30 minutes à 37 °C, l'eau de rinçage redonne un test positif. Un foie bouilli ne redonne pas de glucose.","tache":"Interprète ces résultats."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r32",{"duree":20,"titre":"Diabète et hypoglycémie","accroche":"Une élévation permanente abîme les organes.","intro":"Le diabète résulte d'une régulation défaillante de la glycémie.","objectifs":["distinguer type 1 et type 2","citer les complications","prévenir"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>Le <strong>diabète</strong> se caractérise par une glycémie à jeun égale ou supérieure à 1,26 g/L, vérifiée à deux reprises.</div>"},{"t":"Les types","verrou":true},{"t":"Complications et prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":32,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Dans un quartier de Bafoussam, sur 300 adultes dépistés, 36 ont une glycémie à jeun supérieure à 1,26 g/L et 60 une tension supérieure à 14/9 ; la plupart mangent beaucoup de friture et marchent peu.","tache":"Calcule les pourcentages et rédige des conseils argumentés pour le quartier."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r33",{"duree":20,"titre":"Pression artérielle : mesure et facteurs","accroche":"Deux nombres essentiels.","intro":"La pression artérielle est la force exercée par le sang sur la paroi des artères.","objectifs":["définir systolique et diastolique","mesurer","citer les facteurs"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>La <strong>pression artérielle</strong> s'exprime par deux valeurs : la pression systolique et la pression diastolique.</div>"},{"t":"Mesure","verrou":true},{"t":"Facteurs","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":33,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Une infirmière de Foumban mesure 16/10 chez un commerçant au repos.","tache":"Interprète et conseille."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r34",{"duree":20,"titre":"Élévation et baisse permanentes de la tension","accroche":"L'hypertension est longtemps silencieuse.","intro":"Une tension anormale durable abîme les organes.","objectifs":["citer les conséquences","citer les facteurs de risque","prévenir"],"parties":[{"t":"Définition","html":"<div class='def'><b>Définition</b>L'<strong>hypertension artérielle</strong> est une élévation persistante de la pression artérielle.</div>"},{"t":"Conséquences","verrou":true},{"t":"Prévention","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":34,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Un retraité de Douala arrête son traitement dès qu'il se sent bien.","tache":"Explique-lui le risque."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r35",{"duree":20,"titre":"Intégration : diabète et hypertension","accroche":"Deux maladies liées au mode de vie.","intro":"Cette séance mobilise les notions du chapitre pour résoudre une situation réelle, comme à la partie B de l'épreuve.","objectifs":["identifier le problème","mobiliser les ressources","rédiger une réponse argumentée"],"parties":[{"t":"La notion à mobiliser","html":"<div class='def'><b>Définition</b>Le <strong>diabète de type 2</strong> et l'<strong>hypertension</strong> sont favorisés par une alimentation déséquilibrée et la sédentarité.</div>"},{"t":"Le plan de la réponse","verrou":true},{"t":"La production attendue","verrou":true},{"t":"Entraînement au format de l'examen","verrou":true}],"revision":[],"exo":"","quiz":[],"c":"Tle C","m":"svt","rang":35,"apc":{"module":"Santé reproductive et nutritionnelle","famille":"Choix et observation de saines habitudes de vie","agir":"Lutter contre certaines maladies métaboliques","situation":"Une enquête à Bafoussam montre une hausse du diabète et de l'hypertension chez les commerçants.","tache":"Élabore une affiche de prévention."},"verrou":true,"nq":10,"labo":true});
VRT_L("tle-c-svt-r36",{"duree":20,"titre":"Catastrophes naturelles et gestion","accroche":"Prévoir, prévenir, protéger.","intro":"Le Cameroun connaît volcanisme, glissements de terrain et inondations.","objectifs":["définir aléa et catastrophe","distinguer prévision et prévention","donner des exemples camerounais"],"parties":[{"t":"Définitions","html":"<div class='def'><b>Définition</b>Un <strong>aléa</strong> est un phénomène naturel possible. Une <strong>catastrophe</strong> est un événement qui cause de graves dommages à une société.</div>"},{"t":"Exemples","html":"<ul><li>Éruptions du mont Cameroun.</li><li>Dégazage du lac Nyos en 1986.</li><li>Glissements de terrain, comme à Gouache en 2019 à Bafoussam.</li></ul>","labo":{"type":"pente"}},{"t":"Gestion","html":"<p>La <strong>prévision</strong> estime la survenue ; la <strong>prévention</strong> réduit la vulnérabilité par l'occupation réfléchie des sols et l'information.</p>","retenir":"Prévention : réduire la vulnérabilité."},{"t":"Entraînement au format de l'examen","html":"<div class='integ'><h3>Partie A : évaluation des ressources</h3><p><strong>Évaluation des savoirs (QCM).</strong> Les catastrophes naturelles d'origine interne comprennent :</p><ol type='a'><li>les inondations</li><li>les sécheresses</li><li>les cyclones</li><li>les séismes et les éruptions volcaniques</li></ol><details><summary>Voir la réponse</summary><p><strong>les séismes et les éruptions volcaniques</strong>. Elles sont liées à l'énergie interne de la Terre.</p></details><p><strong>Évaluation des savoir-faire.</strong></p><p>Cite une catastrophe survenue au Cameroun.</p><details><summary>Voir la réponse</summary><p>(Exemple : le lac Nyos en 1986.)</p></details><h3>Partie B : évaluation des compétences</h3><p><strong>Compétence visée.</strong> Prévenir les catastrophes et valoriser les ressources de son environnement.</p><p><strong>Situation.</strong> Après de fortes pluies, des familles construisent au pied d'une colline déboisée ; la commune envisage une évacuation. Un journal parle aussi des inondations dans les bas-fonds.</p><p><strong>Consigne 1.</strong> Distingue aléa, vulnérabilité et risque à partir de cet exemple.</p><p><strong>Consigne 2.</strong> Dans un texte d'une dizaine de lignes, propose à la commune un plan de gestion avant, pendant et après la catastrophe.</p><details><summary>Voir une réponse attendue</summary><p>Aléa : le glissement ou l'inondation possible ; vulnérabilité : les maisons et personnes exposées ; risque : leur combinaison. Avant : cartographier les zones à risque, interdire les constructions, reboiser, drainer, informer. Pendant : alerte, évacuation, secours. Après : prise en charge des sinistrés, évaluation des dégâts, reconstruction hors zone à risque.</p></details></div>","retenir":"Savoir-être mobilisé : Sens de la responsabilité."}],"revision":["Aléa.","Catastrophe.","Prévision et prévention."],"exo":"<p>Cite une catastrophe survenue au Cameroun. <em>(Exemple : le lac Nyos en 1986.)</em></p>","quiz":[{"q":"Les catastrophes naturelles d'origine interne comprennent :","r":["les inondations","les sécheresses","les cyclones","les séismes et les éruptions volcaniques"],"b":3,"e":"Elles sont liées à l'énergie interne de la Terre."},{"q":"La catastrophe du lac Nyos (1986) a été provoquée par :","r":["un dégagement massif de CO₂","une coulée de lave","un tsunami","un séisme seul"],"b":0,"e":"Le gaz a asphyxié les habitants des vallées."},{"q":"Le dégazage du lac Nyos consiste à :","r":["vider le lac","évacuer progressivement le CO₂ dissous par des colonnes","chauffer le lac","remplir le lac"],"b":1,"e":"On empêche une nouvelle accumulation."},{"q":"La dernière éruption du mont Cameroun date de :","r":["1800","1950","2000","2025"],"b":2,"e":"Les coulées ont menacé la route de Limbé."},{"q":"La gestion d'un risque comprend :","r":["l'attente","la panique","rien","la prévision, la prévention, l'alerte et l'organisation des secours"],"b":3,"e":"Elle réduit la vulnérabilité des populations."},{"q":"Un plan d'évacuation doit indiquer :","r":["les itinéraires et les lieux de regroupement","les meilleurs restaurants","rien","les numéros de jeux"],"b":0,"e":"Chacun doit savoir où aller."},{"q":"Pendant un séisme à l'intérieur, il faut :","r":["courir dans les escaliers","s'abriter sous un meuble solide, loin des vitres","prendre l'ascenseur","se placer près des fenêtres"],"b":1,"e":"On se protège des chutes d'objets."},{"q":"Les constructions parasismiques :","r":["s'effondrent plus vite","sont interdites","résistent mieux aux secousses","n'existent pas"],"b":2,"e":"Elles respectent des normes de chaînage."},{"q":"Le risque est le produit :","r":["du hasard seul","de la météo","de la population seule","de l'aléa et de la vulnérabilité"],"b":3,"e":"Une zone dangereuse inhabitée a un risque faible."},{"q":"La surveillance d'un volcan utilise :","r":["des sismographes, des mesures de gaz et de déformation du sol","un thermomètre de cuisine","un glucomètre","rien"],"b":0,"e":"Elle permet de lancer l'alerte à temps."}],"c":"Tle C","m":"svt","rang":36,"apc":{"module":"Catastrophes et valorisation","famille":"Préservation de l'environnement","agir":"Prévenir les catastrophes et valoriser les ressources de son environnement","situation":"Des familles de Bafoussam construisent au pied d'une colline qui s'effondre à chaque pluie abondante.","tache":"Propose une conduite."},"gratuit":true});
